package main

import (
	"encoding/json"
	"fmt"
)

type User struct {
	Name     string `json:"name"`
	Age      int    `json:"age"`
	Email    string `json:"email,omitempty"`
	Admin    bool   `json:"admin"`
	password string
}

func main() {
	ada := User{Name: "Ada", Age: 36, password: "secret"}
	data, err := json.Marshal(ada)
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Println(string(data))

	bob := User{Name: "Bob", Age: 29, Email: "bob@example.com", Admin: true}
	pretty, err := json.MarshalIndent(bob, "", "  ")
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Println(string(pretty))

	stock := map[string]int{"pears": 2, "apples": 5}
	data, err = json.Marshal(stock)
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Println(string(data))
}

