)

type User struct {
	Name  string `json:"name"`
	Age   int    `json:"age"`
	Email string `json:"email,omitempty"`
	Admin bool   `json:"admin"`
}

func main() {
	var u User
	err := json.Unmarshal([]byte(`{"name":"Grace","age":45,"admin":true,"team":"navy"}`), &u)
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Println(u.Name, u.Age, u.Admin, u.Email == "")

	var stock map[string]int
	err = json.Unmarshal([]byte(`{"pears":3,"apples":5}`), &stock)
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Println(stock, stock["apples"])

	var broken User
	err = json.Unmarshal([]byte(`{"name":`), &broken)
	if err != nil {
		fmt.Println("error:", err)
	}
}

