package main

import (
	"encoding/json"
	"fmt"
)

type Config struct {
	Host  string `json:"host"`
	Port  int    `json:"port"`
	Debug bool   `json:"debug"`
}

func main() {
	var cfg Config
	err := json.Unmarshal([]byte(`{"host":"localhost","port":8080,"debug":true,"extra":1}`), &cfg)
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Printf("%+v\n", cfg)

	var votes map[string]int
	err = json.Unmarshal([]byte(`{"red":2,"blue":7}`), &votes)
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Println(votes, votes["blue"])

	var nums []int
	err = json.Unmarshal([]byte(`[1, 2`), &nums)
	if err != nil {
		fmt.Println("error:", err)
	}
}

